package org.agentos.lab;
import android.graphics.*;
import android.media.*;
import android.opengl.*;
import android.os.*;
import android.view.Surface;
import java.io.*;
import java.nio.*;
import org.json.*;
/** Standard decoder SurfaceTexture -> external OES -> offscreen EGL probe. No Activity/display. */
public final class TextureDecodeProbe {
 static FloatBuffer floats(float[] x){FloatBuffer f=ByteBuffer.allocateDirect(x.length*4).order(ByteOrder.nativeOrder()).asFloatBuffer();f.put(x).position(0);return f;}
 static int shader(int type,String source){int s=GLES20.glCreateShader(type);GLES20.glShaderSource(s,source);GLES20.glCompileShader(s);int[] ok=new int[1];GLES20.glGetShaderiv(s,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetShaderInfoLog(s));return s;}
 static void picture(ByteBuffer rgba,int w,int h,String path)throws Exception{rgba.position(0);int[] pixels=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int r=rgba.get()&255,g=rgba.get()&255,b=rgba.get()&255,a=rgba.get()&255;pixels[(h-1-y)*w+x]=a<<24|r<<16|g<<8|b;}Bitmap bmp=Bitmap.createBitmap(pixels,w,h,Bitmap.Config.ARGB_8888);try(FileOutputStream f=new FileOutputStream(path)){bmp.compress(Bitmap.CompressFormat.PNG,100,f);}bmp.recycle();}
 public static void main(String[] args)throws Exception{
  JSONObject result=new JSONObject().put("codec",args[0]).put("input",args[1]).put("path","SurfaceTexture/external-OES/EGL-pbuffer");JSONArray frames=new JSONArray();result.put("frames",frames);MediaExtractor ex=new MediaExtractor();MediaCodec dec=null;SurfaceTexture texture=null;Surface target=null;EGLDisplay display=EGL14.EGL_NO_DISPLAY;EGLSurface offscreen=EGL14.EGL_NO_SURFACE;EGLContext context=EGL14.EGL_NO_CONTEXT;HandlerThread callbacks=new HandlerThread("texture-probe-callback");callbacks.start();final Object signal=new Object();final boolean[] available={false};
  try{
   ex.setDataSource(args[1]);int track=-1;for(int i=0;i<ex.getTrackCount();i++)if(ex.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("video/")){track=i;break;}if(track<0)throw new IOException("No video track");ex.selectTrack(track);MediaFormat format=ex.getTrackFormat(track);int w=format.getInteger(MediaFormat.KEY_WIDTH),h=format.getInteger(MediaFormat.KEY_HEIGHT);result.put("inputFormat",format.toString());
   display=EGL14.eglGetDisplay(EGL14.EGL_DEFAULT_DISPLAY);int[] vers=new int[2];if(!EGL14.eglInitialize(display,vers,0,vers,1))throw new IOException("eglInitialize "+EGL14.eglGetError());int[] configAttrs={EGL14.EGL_RED_SIZE,8,EGL14.EGL_GREEN_SIZE,8,EGL14.EGL_BLUE_SIZE,8,EGL14.EGL_ALPHA_SIZE,8,EGL14.EGL_RENDERABLE_TYPE,EGL14.EGL_OPENGL_ES2_BIT,EGL14.EGL_SURFACE_TYPE,EGL14.EGL_PBUFFER_BIT,EGL14.EGL_NONE};EGLConfig[] configs=new EGLConfig[1];int[] num=new int[1];if(!EGL14.eglChooseConfig(display,configAttrs,0,configs,0,1,num,0)||num[0]==0)throw new IOException("eglChooseConfig");context=EGL14.eglCreateContext(display,configs[0],EGL14.EGL_NO_CONTEXT,new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION,2,EGL14.EGL_NONE},0);offscreen=EGL14.eglCreatePbufferSurface(display,configs[0],new int[]{EGL14.EGL_WIDTH,w,EGL14.EGL_HEIGHT,h,EGL14.EGL_NONE},0);if(!EGL14.eglMakeCurrent(display,offscreen,offscreen,context))throw new IOException("eglMakeCurrent "+EGL14.eglGetError());result.put("renderer",GLES20.glGetString(GLES20.GL_RENDERER)).put("vendor",GLES20.glGetString(GLES20.GL_VENDOR)).put("glVersion",GLES20.glGetString(GLES20.GL_VERSION));
   int[] ids=new int[1];GLES20.glGenTextures(1,ids,0);GLES20.glBindTexture(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,ids[0]);GLES20.glTexParameteri(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,GLES20.GL_TEXTURE_MIN_FILTER,GLES20.GL_NEAREST);GLES20.glTexParameteri(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,GLES20.GL_TEXTURE_MAG_FILTER,GLES20.GL_NEAREST);GLES20.glTexParameteri(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,GLES20.GL_TEXTURE_WRAP_S,GLES20.GL_CLAMP_TO_EDGE);GLES20.glTexParameteri(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,GLES20.GL_TEXTURE_WRAP_T,GLES20.GL_CLAMP_TO_EDGE);
   texture=new SurfaceTexture(ids[0]);texture.setDefaultBufferSize(w,h);texture.setOnFrameAvailableListener(t->{synchronized(signal){available[0]=true;signal.notifyAll();}},new Handler(callbacks.getLooper()));target=new Surface(texture);
   int vs=shader(GLES20.GL_VERTEX_SHADER,"attribute vec4 p; attribute vec2 t; uniform mat4 m; varying vec2 uv; void main(){ gl_Position=p; uv=(m*vec4(t,0.0,1.0)).xy; }");int fs=shader(GLES20.GL_FRAGMENT_SHADER,"#extension GL_OES_EGL_image_external : require\nprecision mediump float; uniform samplerExternalOES s; varying vec2 uv; void main(){gl_FragColor=texture2D(s,uv);}");int program=GLES20.glCreateProgram();GLES20.glAttachShader(program,vs);GLES20.glAttachShader(program,fs);GLES20.glLinkProgram(program);int[] linked=new int[1];GLES20.glGetProgramiv(program,GLES20.GL_LINK_STATUS,linked,0);if(linked[0]==0)throw new IOException(GLES20.glGetProgramInfoLog(program));GLES20.glUseProgram(program);int pa=GLES20.glGetAttribLocation(program,"p"),ta=GLES20.glGetAttribLocation(program,"t"),ma=GLES20.glGetUniformLocation(program,"m");GLES20.glVertexAttribPointer(pa,2,GLES20.GL_FLOAT,false,0,floats(new float[]{-1,-1,1,-1,-1,1,1,1}));GLES20.glEnableVertexAttribArray(pa);GLES20.glVertexAttribPointer(ta,2,GLES20.GL_FLOAT,false,0,floats(new float[]{0,0,1,0,0,1,1,1}));GLES20.glEnableVertexAttribArray(ta);GLES20.glUniform1i(GLES20.glGetUniformLocation(program,"s"),0);GLES20.glViewport(0,0,w,h);
   dec=MediaCodec.createByCodecName(args[0]);dec.configure(format,target,null,0);dec.start();boolean inputDone=false,outputDone=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long end=SystemClock.elapsedRealtime()+20000;float[] matrix=new float[16];ByteBuffer pixels=ByteBuffer.allocateDirect(w*h*4);
   while(!outputDone&&SystemClock.elapsedRealtime()<end){if(!inputDone){int ix=dec.dequeueInputBuffer(10000);if(ix>=0){int sz=ex.readSampleData(dec.getInputBuffer(ix),0);if(sz<0){dec.queueInputBuffer(ix,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputDone=true;}else{dec.queueInputBuffer(ix,0,sz,ex.getSampleTime(),0);ex.advance();}}}int ox=dec.dequeueOutputBuffer(info,10000);if(ox==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED)result.put("outputFormat",dec.getOutputFormat().toString());else if(ox>=0){boolean eos=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0,data=info.size>0||!eos;dec.releaseOutputBuffer(ox,data);if(data){long until=SystemClock.elapsedRealtime()+2000;synchronized(signal){while(!available[0]&&SystemClock.elapsedRealtime()<until)signal.wait(50);if(!available[0])throw new IOException("SurfaceTexture frame timeout");available[0]=false;}texture.updateTexImage();texture.getTransformMatrix(matrix);GLES20.glUniformMatrix4fv(ma,1,false,matrix,0);GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP,0,4);pixels.position(0);GLES20.glReadPixels(0,0,w,h,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,pixels);int err=GLES20.glGetError();JSONObject frame=new JSONObject().put("ptsUs",info.presentationTimeUs).put("textureTimestampNs",texture.getTimestamp()).put("glError",err);if(frames.length()==0||frames.length()==8){String png=args[2]+"-"+frames.length()+".png";picture(pixels,w,h,png);frame.put("png",png);}frames.put(frame);}outputDone=eos;}}
   result.put("frameCount",frames.length()).put("eos",outputDone);
  }catch(Exception error){result.put("error",error.toString());}
  finally{if(dec!=null){try{dec.stop();}catch(Exception ignored){}dec.release();}if(target!=null)target.release();if(texture!=null)texture.release();callbacks.quitSafely();ex.release();if(display!=EGL14.EGL_NO_DISPLAY){EGL14.eglMakeCurrent(display,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_CONTEXT);if(offscreen!=EGL14.EGL_NO_SURFACE)EGL14.eglDestroySurface(display,offscreen);if(context!=EGL14.EGL_NO_CONTEXT)EGL14.eglDestroyContext(display,context);EGL14.eglTerminate(display);}}
  System.out.println(result.toString(2));
 }
}
